INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:تبع:zabidi_taj_arus', 'تبع', 'dd530847a4fdd7102a3d3e0617', 'تَبِعَهُ، كفَرِحَ يَتْبَعُهُ تَبَعاً، مُحَرَّكَةً، وَتَبَاعَةً، كسَحَابَةٍ: مَشَى خَلْفَهُ أَوْ مَرَّ بِهِ فمَضَى مَعَهُ', 'walked behind him, or went along with him', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_a395ad902c520a7e', '372', 20, 'blk_taj_edd43a87beccdf8d', 0, NULL, 'Marker: Qāmūs gloss. Reading: following.', 'high', 'active');
