UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: keeping at. Differs from the main reading (group, gathering).', updated_at = datetime('now') WHERE id = 'ASL:ثبي:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
